#pragma once
// Painting for the settings page, on the start-up screens' canvas (ui/startup_canvas.hpp, a 32-bit
// A8B8G8R8 buffer the CPU writes): translucent and rounded rectangles, and text in the page's own
// font (ui/ui_font_data.hpp: Inter as 4-bit coverage, generated by tools/make_ui_font.cpp).
// SDK-free; the host tests draw with it.
#include "ui/startup_canvas.hpp"
#include "ui/ui_font_data.hpp"

#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstring>

namespace twv::ui {

// `src` over `dst` at `alpha` (0..255); the result is opaque.
constexpr uint32_t mix(uint32_t dst, uint32_t src, unsigned alpha) {
    const uint32_t a = alpha + (alpha >> 7); // 0..256
    const uint32_t rb = (((src & 0x00ff00ffu) * a + (dst & 0x00ff00ffu) * (256u - a)) >> 8) & 0x00ff00ffu;
    const uint32_t g = (((src & 0x0000ff00u) * a + (dst & 0x0000ff00u) * (256u - a)) >> 8) & 0x0000ff00u;
    return 0xff000000u | rb | g;
}

inline void blend_rect(const Canvas& c, int x, int y, int w, int h, uint32_t color, unsigned alpha) {
    if (alpha >= 255) {
        fill_rect(c, x, y, w, h, color);
        return;
    }
    const int x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;
    const int x1 = x + w > c.width ? c.width : x + w, y1 = y + h > c.height ? c.height : y + h;
    for (int yy = y0; yy < y1; ++yy) {
        uint32_t* row = c.pixels + std::size_t(yy) * std::size_t(c.stride);
        for (int xx = x0; xx < x1; ++xx) row[xx] = mix(row[xx], color, alpha);
    }
}

// A filled rectangle with round corners of `radius` pixels, its edge smoothed. A radius of half
// the smaller side gives a pill, or a disc for a square.
inline void round_rect(const Canvas& c, int x, int y, int w, int h, int radius, uint32_t color, unsigned alpha = 255) {
    if (w <= 0 || h <= 0) return;
    if (radius * 2 > w) radius = w / 2;
    if (radius * 2 > h) radius = h / 2;
    if (radius <= 0) {
        blend_rect(c, x, y, w, h, color, alpha);
        return;
    }
    // The straight parts, then the four corners pixel by pixel.
    blend_rect(c, x + radius, y, w - 2 * radius, h, color, alpha);
    blend_rect(c, x, y + radius, radius, h - 2 * radius, color, alpha);
    blend_rect(c, x + w - radius, y + radius, radius, h - 2 * radius, color, alpha);
    const float r = float(radius);
    for (int cy = 0; cy < radius; ++cy) {
        for (int cx = 0; cx < radius; ++cx) {
            // Distance of this pixel's centre from the corner's centre.
            const float dx = r - (float(cx) + 0.5f), dy = r - (float(cy) + 0.5f);
            const float cover = r - std::sqrt(dx * dx + dy * dy) + 0.5f;
            if (cover <= 0.0f) continue;
            const unsigned a = cover >= 1.0f ? alpha : unsigned(float(alpha) * cover);
            const int xs[2] = {x + cx, x + w - 1 - cx}, ys[2] = {y + cy, y + h - 1 - cy};
            for (int py : ys)
                for (int px : xs) {
                    if (px < 0 || py < 0 || px >= c.width || py >= c.height) continue;
                    uint32_t& p = c.pixels[std::size_t(py) * std::size_t(c.stride) + std::size_t(px)];
                    p = mix(p, color, a);
                }
        }
    }
}

constexpr std::size_t WholeText = ~std::size_t(0);

inline const font::Glyph& glyph_of(const font::Font& f, char ch) {
    const int code = static_cast<unsigned char>(ch);
    return f.glyphs[(code >= font::FirstGlyph && code < font::FirstGlyph + font::GlyphCount ? code : '?') -
                    font::FirstGlyph];
}

// Width in pixels of the first `count` characters of `text`.
inline int text_width(const font::Font& f, const char* text, std::size_t count = WholeText) {
    int pen16 = 0;
    for (std::size_t i = 0; i < count && text[i]; ++i) pen16 += glyph_of(f, text[i]).advance16;
    return (pen16 + 15) / 16;
}

// Draws `text` with its line's top at `y`; returns the pen advance in pixels.
inline int draw_text(const Canvas& c, const font::Font& f, int x, int y, uint32_t color, const char* text,
                     std::size_t count = WholeText, unsigned alpha = 255) {
    int pen16 = 0;
    const int baseline = y + f.ascent;
    for (std::size_t i = 0; i < count && text[i]; ++i) {
        const font::Glyph& g = glyph_of(f, text[i]);
        const int gx = x + (pen16 + 8) / 16 + g.left, gy = baseline + g.top;
        const uint8_t* data = f.coverage + g.offset;
        for (int row = 0; row < g.height; ++row) {
            const int py = gy + row;
            if (py < 0 || py >= c.height) continue;
            uint32_t* line = c.pixels + std::size_t(py) * std::size_t(c.stride);
            for (int col = 0; col < g.width; ++col) {
                const int px = gx + col;
                if (px < 0 || px >= c.width) continue;
                const int at = row * g.width + col;
                const unsigned nibble = at & 1 ? data[at / 2] & 15u : data[at / 2] >> 4;
                if (nibble) line[px] = mix(line[px], color, nibble * alpha / 15u);
            }
        }
        pen16 += g.advance16;
    }
    return (pen16 + 15) / 16;
}

inline void draw_text_right(const Canvas& c, const font::Font& f, int right, int y, uint32_t color, const char* text) {
    draw_text(c, f, right - text_width(f, text), y, color, text);
}
inline void draw_text_centred(const Canvas& c, const font::Font& f, int centre, int y, uint32_t color, const char* text) {
    draw_text(c, f, centre - text_width(f, text) / 2, y, color, text);
}

// Word wrap to `width` pixels: fills `lines` (start, length), returns the count; `truncated` when
// the text needs more than `maxLines`. A word longer than a line is cut.
inline int wrap_text(const font::Font& f, const char* text, int width, TextLine* lines, int maxLines,
                     bool* truncated = nullptr) {
    if (truncated) *truncated = false;
    const std::size_t n = std::strlen(text);
    std::size_t at = 0;
    int count = 0;
    while (at < n) {
        while (at < n && text[at] == ' ') ++at;
        if (at >= n) break;
        if (count == maxLines) {
            if (truncated) *truncated = true;
            break;
        }
        std::size_t end = at, lastBreak = at;
        int pen16 = 0;
        while (end < n) {
            pen16 += glyph_of(f, text[end]).advance16;
            if ((pen16 + 15) / 16 > width) break;
            ++end;
            if (end == n || text[end] == ' ') lastBreak = end;
        }
        if (end < n) end = lastBreak > at ? lastBreak : (end > at ? end : at + 1);
        lines[count++] = {at, end - at};
        at = end;
    }
    return count;
}

} // namespace twv::ui
